import AirlockCore
import AppKit

/// The calling app's logo as a one-colour outline, for the call pill.
///
/// Drawn from Simple Icons (simpleicons.org, CC0, 16.34.0): each app's own
/// brand glyph on a 24 × 24 canvas, a single path. Template images, so the
/// pill tints them like the cup and tray beside it. The app's real icon was
/// tried first — cropped to a circle and greyed — and at 11pt it read as a
/// smudge (owner, 2026-10-07: "the whatsapp logo is weird").
///
/// Only apps whose logo is a SHAPE are here. Zoom's is the word "zoom", which
/// is unreadable at this size, so it gets the camera; everything not listed
/// gets the phone (see `CallPill`). A call in a browser shows the browser,
/// or Meet's camera when the tab is a Meet (`site(inWindowTitles:)`).
@MainActor
enum CallGlyph {
    /// What to draw for a call in this app.
    enum Kind: Equatable {
        /// A brand logo, from `image(_:)`.
        case logo(String)
        /// An SF Symbol.
        case symbol(String)
    }

    static func kind(for call: OngoingCall) -> Kind {
        if call.site == .googleMeet { return .logo("googlemeet") }
        return kind(for: call.bundleID)
    }

    static func kind(for bundleID: String) -> Kind {
        if let name = logoNames[bundleID] { return .logo(name) }
        if bundleID == "us.zoom.xos" { return .symbol("video.fill") }
        return .symbol("phone.fill")
    }

    /// Bundle IDs → logo. Both builds where an app ships two (WhatsApp's
    /// native app and its older desktop one; Telegram's two Mac clients).
    static let logoNames: [String: String] = [
        "net.whatsapp.WhatsApp": "whatsapp",
        "desktop.WhatsApp": "whatsapp",
        "com.hnc.Discord": "discord",
        "com.hnc.DiscordPTB": "discord",
        "com.hnc.DiscordCanary": "discord",
        "com.tinyspeck.slackmacgap": "slack",
        "ru.keepcoder.Telegram": "telegram",
        "org.telegram.desktop": "telegram",
        "org.whispersystems.signal-desktop": "signal",
        // A call in a browser (Meet, Teams on the web, a Zoom link) is
        // credited to the browser, so the logo says where the call's tab is.
        "com.google.Chrome": "chrome",
        "com.google.Chrome.beta": "chrome",
        "com.google.Chrome.canary": "chrome",
        "com.apple.Safari": "safari",
        "com.apple.SafariTechnologyPreview": "safari",
        "org.mozilla.firefox": "firefox",
        "company.thebrowser.Browser": "arc",
        "com.brave.Browser": "brave",
        "com.operasoftware.Opera": "opera",
        "com.vivaldi.Vivaldi": "vivaldi",
    ]

    static func isBrowser(_ bundleID: String) -> Bool {
        logoNames[bundleID].map(browserLogos.contains) ?? false
    }

    private static let browserLogos: Set<String> = [
        "chrome", "safari", "firefox", "arc", "brave", "opera", "vivaldi",
    ]

    /// Meet, when one of a browser's window titles is a Meet tab: "Meet –
    /// abc-defg-hij" or "Meet – <meeting name>", with whatever the browser
    /// appends after it. Other services' tabs are left to the browser's logo:
    /// only Meet has a logo here, and Teams and Zoom on the web do not title
    /// their tabs in one steady way.
    static func site(inWindowTitles titles: [String]) -> MeetingLink.Provider? {
        let isMeet = titles.contains { title in
            title == "Meet" || ["Meet - ", "Meet – ", "Meet — "].contains { title.hasPrefix($0) }
                || title.contains("meet.google.com")
        }
        return isMeet ? .googleMeet : nil
    }

    /// The logo as a template image, or nil for an unknown name. Built once.
    static func image(_ name: String) -> NSImage? {
        if let cached = images[name] { return cached }
        guard let path = paths[name],
              let image = NSImage(data: Data(svg(path).utf8)) else { return nil }
        image.isTemplate = true
        images[name] = image
        return image
    }

    private static var images: [String: NSImage] = [:]

    private static func svg(_ path: String) -> String {
        #"<svg viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg"><path d=""# + path + #""/></svg>"#
    }

